def render(title,rows):
 width=680;y=96;parts=[]
 for i,(heading,body) in enumerate(rows):
  lines=textwrap.wrap(body,49);height=66+len(lines)*27
  parts.append(f'<rect x="22" y="{y}" width="636" height="{height}" rx="16" fill="{["#e3efe8","#edf1e3"][i%2]}"/>')
  parts.append(f'<text x="42" y="{y+32}" font-size="24" font-weight="700">{escape(heading)}</text>')
  for j,line in enumerate(lines):parts.append(f'<text x="42" y="{y+65+j*27}" font-size="22">{escape(line)}</text>')
  y+=height+14
 return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} {y+22}" role="img" aria-labelledby="t d"><title id="t">{escape(title)}</title><desc id="d">Смысловая структурная схема: '+escape('; '.join(h+': '+b for h,b in rows))+f'</desc><rect width="680" height="{y+22}" rx="20" fill="#fafbf8"/><g font-family="Arial,sans-serif" fill="#234c3c"><text x="28" y="40" font-size="26" font-weight="700">{escape(title)}</text><text x="28" y="70" font-size="17" fill="#62776d">Структуры и связи · учебная схема</text>'+''.join(parts)+'</g></svg>\n'
if __name__=='__main__':
 for name,(title,rows) in DIAGRAMS.items():(ROOT/(name+'.svg')).write_text(render(title,rows))
 print(f'Rendered {len(DIAGRAMS)} subject-specific diagrams')
